        [1300] = {
            ["La vida es como un tapiz delicadamente tejido."] = "e70d13a96c407b1d174c59f1f077a835",
            ["Mmm... Las cosas que necesitas aprender me sobrepasan. Ve a hablar con Sellandus en la Sastrería Larson, en la parte de arriba del camino a la derecha. ¡Él me enseñó todo lo que sé!"] = "35b7486429188df700dbf11b3bbcbd82",
            ["Muy bien, que comience tu viaje al mundo de la sastrería."] = "c5f30755100cfd7f05cda25a366d0602",
        },
        [1301] = {
            ["Los mejores precios en todo Ventormenta, no encontrarás mejores precios. Y bien, ¿en qué puedo ayudarte?"] = "930e45368ed7dcac8e799df8fa5bc730",
